#!/bin/bash
# Download every external artifact this environment needs (idempotent).
#
# Estimated total download size: 0.25 GB
# Estimated disk usage after extraction: 0.25 GB
#
# The benchmark scenes themselves are agent-authored data committed under
# data/glav_syn/ (method-visible inputs) and eval/*/answers.pt (evaluator-owned
# targets); they are regenerated by eval/test/build_benchmark.py if needed.
# The only external assets are the LPIPS (v0.1, AlexNet) weights used by the
# evaluators.
set -euo pipefail
cd /home/user

DEST=data/downloads/lpips
mkdir -p "$DEST"

fetch() {  # url, file, sha256
  local url="$1" file="$2" sum="$3"
  if [ -s "$file" ] && echo "$sum  $file" | sha256sum -c --status; then
    echo "present: $file"
    return
  fi
  curl -fsSL --retry 3 -o "$file.part" "$url"
  mv "$file.part" "$file"
  echo "$sum  $file" | sha256sum -c
}

fetch https://download.pytorch.org/models/alexnet-owt-7be5be79.pth \
  "$DEST/alexnet-owt-7be5be79.pth" 7be5be791159472b1fbf3c69796f7cb30dca7ad8466c2df70058c37116cdee02
fetch https://github.com/richzhang/PerceptualSimilarity/raw/master/lpips/weights/v0.1/alex.pth \
  "$DEST/alex_v0.1.pth" df73285e35b22355a2df87cdb6b70b343713b667eddbda73e1977e0c860835c0
